5.query:
timeseries {
  graphql_errors = count(`http.server.request.duration`, filter: `graphql.errors` == "true"),
  http_errors = count(`http.server.request.duration`, filter: not (startsWith(`http.response.status_code`, "2") or startsWith(`http.response.status_code`, "4"))),
  total = count(`http.server.request.duration`)
}
| fieldsAdd error_rate_pct = ((graphql_errors[] + http_errors[]) / total[]) * 100

50.query:
timeseries {
  misses = count(`apollo.router.cache.miss.time`),
  hits = count(`apollo.router.cache.hit.time`),
  records = sum(`apollo.router.cache.size`, rollup: avg)
}
| fieldsAdd hit_rate_pct = (hits[] / (hits[] + misses[])) * 100

58.query:
timeseries {
  hits = count(`apollo.router.cache.hit.time`),
  misses = count(`apollo.router.cache.miss.time`)
}, by: {`host.name`, `k8s.pod.name`, `container.id`}
| fieldsAdd hit_rate_pct = (hits[] / (hits[] + misses[])) * 100

61.query:
timeseries {
  exec_p50 = percentile(`apollo.router.compute_jobs.execution.duration`, 50, filter: `job.type` == "query_planning"),
  exec_p95 = percentile(`apollo.router.compute_jobs.execution.duration`, 95, filter: `job.type` == "query_planning"),
  exec_p99 = percentile(`apollo.router.compute_jobs.execution.duration`, 99, filter: `job.type` == "query_planning"),
  wait_avg = avg(`apollo.router.compute_jobs.queue.wait.duration`, filter: `job.type` == "query_planning")
}

