87.query:
timeseries {
  success = sum(`apollo.router.operations.coprocessor`, filter: `coprocessor.succeeded` == "true"),
  total = sum(`apollo.router.operations.coprocessor`)
}, by: {`coprocessor.stage`}
| fieldsAdd success_rate_pct = (success[] / total[]) * 100

90.query:
timeseries {
  uplink_fetch_duration = avg(`apollo.router.uplink.fetch.duration.seconds`),
  licensed = sum(`apollo.router.lifecycle.license`, filter: `license.state` == "licensed"),
  license_total = sum(`apollo.router.lifecycle.license`)
}
| fieldsAdd licensed_pct = (licensed[] / license_total[]) * 100

96.query:
timeseries {
  requests = count(`http.client.request.duration`),
  p95_latency = percentile(`http.client.request.duration`, 95)
}, by: {`subgraph.name`}
| filter isNotNull(`subgraph.name`)
| summarize requests = sum(arraySum(requests)), p95_latency = avg(arrayAvg(p95_latency)), by: {`subgraph.name`}
| sort requests desc
| limit 12

